insert into public.grapes (name, color, description, skin_color)
values ('Marquette', 'RED', 'A red hybrid grape bred at the University of Minnesota by Peter Hemstad and James Luby from Minnesota 1094 and Ravat Noir, crossed in 1989 and released in 2006. It is grown in very cold climates for red wine, with good resistance to mildew and black rot.', 'blue-black')
on conflict (name) do nothing;
insert into public.grapes (name, color, description, skin_color)
values ('Frontenac', 'RED', 'A red hybrid grape bred at the University of Minnesota from Landot Noir and a very cold-hardy Vitis riparia, and released in 1996. It survives winters of about −35 °F and is made into dry red, rosé and port-style wines.', 'blue-black')
on conflict (name) do nothing;
insert into public.grapes (name, color, description, skin_color)
values ('La Crescent', 'WHITE', 'A white hybrid grape bred at the University of Minnesota by Peter Hemstad and James Luby from St. Pepin and Elmer Swenson 6-8-25, crossed in 1988 and released in 2002. Its wines have aromas of citrus, apricot, pineapple and muscat.', 'green')
on conflict (name) do nothing;
insert into public.grapes (name, color, description, skin_color)
values ('Seyval Blanc', 'WHITE', 'A white French-American hybrid bred by Bertille Seyve-Villard from Seibel 5656 and Rayon d''Or. It is grown in cool climates such as New York''s Hudson Valley for crisp white wines with citrus notes.', 'green')
on conflict (name) do nothing;
insert into public.grapes (name, color, description, skin_color)
values ('Vidal Blanc', 'WHITE', 'A white French hybrid bred by Jean-Louis Vidal from Ugni Blanc and Rayon d''Or. Its fruit is fruity, with grapefruit and pineapple notes, and its tough skin suits it to ice wine in cold climates.', 'green')
on conflict (name) do nothing;
insert into public.grapes (name, color, description, skin_color)
values ('Baco Noir', 'RED', 'A red French hybrid bred by François Baco in 1902 from Folle Blanche and a Vitis riparia. It makes deeply coloured red wines with blueberry and plum notes in cool northern climates such as New York and Ontario.', 'blue-black')
on conflict (name) do nothing;

-- united-states.new-york.champlain-valley-of-new-york
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'New York''s northernmost wine region, about 500 square miles in Clinton and Essex counties along the western shore of Lake Champlain, running north to the Canadian border. Its growing season is short, about four weeks shorter than across the lake at South Hero, Vermont, so it is planted to cold-hardy hybrids from the University of Minnesota rather than to vinifera.', 'A season of about 160 days, with later spring frosts and earlier autumn frosts than nearby areas. Westerly winds carry the lake''s warmth to Vermont rather than to the AVA, so its climate follows the Adirondacks to the west.', 'Sand and clay, rich in minerals and generally well drained, left in a flat valley between the Adirondacks and the lake after the last ice sheet and the Champlain Sea retreated.', 'Cold-hardy hybrids: Marquette, Frontenac and La Crescent, with small trial plantings of vinifera.', 'Red wines from Marquette and Frontenac, and aromatic white wine from La Crescent.', array['Established 2016 (27 CFR 9.258)', 'Clinton and Essex counties', '11 commercial vineyards and 6 wineries at approval (T.D. TTB-142)', 'About 122 acres under vine on 21 farms (New York Wine & Grape Foundation)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.new-york.champlain-valley-of-new-york';
insert into public.wine_place_styles (wine_place_id, style, sort_order, editorial_status)
select id, 'RED', 0, 'PUBLISHED' from public.wine_places where canonical_key = 'united-states.new-york.champlain-valley-of-new-york';
insert into public.wine_place_styles (wine_place_id, style, sort_order, editorial_status)
select id, 'WHITE', 1, 'PUBLISHED' from public.wine_places where canonical_key = 'united-states.new-york.champlain-valley-of-new-york';
insert into public.wine_place_grapes (wine_place_id, grape_id, role, permitted, share_pct, local_note, editorial_status)
select p.id, g.id, 'PRINCIPAL', true, null, null, 'PUBLISHED'
  from public.wine_places p, public.grapes g
 where p.canonical_key = 'united-states.new-york.champlain-valley-of-new-york' and g.name = 'Marquette';
insert into public.wine_place_grapes (wine_place_id, grape_id, role, permitted, share_pct, local_note, editorial_status)
