-- united-states.new-york.finger-lakes.cayuga-lake
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA around Cayuga Lake, north of Ithaca, in Cayuga, Seneca and Tompkins counties, within the Finger Lakes AVA. In 1988 it became the first AVA established inside the Finger Lakes. The lake, more than 430 feet deep, stores summer heat and tempers the vineyards on the gentle hills around it.', 'Cold air drains down the slopes in summer and the lake gives back stored heat in autumn, lowering the risk of early frost; the growing season runs about 165 to 170 days, against about 145 across much of the Finger Lakes.', 'Soils formed mainly from shale bedrock, as the petition described it, in a glacial basin separated from Seneca Lake''s by both topography and soil; limestone and slate lie to the north and sandstone and shale to the south.', 'Riesling is the benchmark grape, with Pinot Noir and Cabernet Franc gaining ground, and Chardonnay and Gewürztraminer.', 'White wines from Riesling, Chardonnay and Gewürztraminer, and red wines from Pinot Noir and Cabernet Franc.', array['Established 1988 (27 CFR 9.127)', 'Cayuga, Seneca and Tompkins counties', '8 bonded wineries and 18 vineyards on about 460 acres when proposed', 'The first AVA established within the Finger Lakes AVA']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.new-york.finger-lakes.cayuga-lake';
