-- united-states.new-york.finger-lakes.seneca-lake
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA of about 204,600 acres around Seneca Lake in Ontario, Schuyler, Seneca and Yates counties, entirely within the Finger Lakes AVA. Seneca is the largest of the Finger Lakes, up to 634 feet deep, and its deep water stays near 39 °F all year, so the surface rarely freezes. Tender vinifera grow near the shore and hardier American and hybrid grapes on the upper slopes.', 'The longest growing season in the Finger Lakes, about 190 days, as the lake protects vineyards from spring frost and autumn freezes; the hills around it rise about 445 feet above the shore.', 'Glacial soils on the slopes of a basin carved by the ice sheets; the most tender vines are planted within about half a mile of the water.', 'Riesling leads, in styles from bone dry to late harvest, with Chardonnay, Cabernet Franc, Pinot Noir, Gewürztraminer and Lemberger.', 'White wines from Riesling, dry to sweet late-harvest, Chardonnay and Gewürztraminer, and red wines from Cabernet Franc, Pinot Noir and Lemberger.', array['Established 2003 (27 CFR 9.128)', 'Ontario, Schuyler, Seneca and Yates counties', 'About 3,756 acres of grapes and 33 wineries at approval (T.D. TTB-3)', 'The lake covers 67.7 square miles (T.D. TTB-3)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.new-york.finger-lakes.seneca-lake';
