-- united-states.new-york.hudson-river-region
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA in the Hudson Valley north of New York City, in Columbia, Dutchess, Orange, Putnam, Rockland, Sullivan, Ulster and Westchester counties, and one of the oldest wine regions in the country. French Huguenots tried vinifera at New Paltz in the late 1600s, Croton Point planted the first commercial vineyard in 1827, and the valley helped develop French-American hybrids such as Seyval Blanc and Baco Noir.', 'The valley funnels in maritime air, bringing hot days and humid nights; summers average about 74 °F and winters, with winds from Canada, about 21 °F. The season runs about 190 days, and July is wetter than in the rest of the state while September and October are drier.', 'Varied glacial soils: gravel, alluvium, moraine, shale and limestone, which drain differently from site to site.', 'Hybrids such as Seyval Blanc, Baco Noir and Vidal Blanc, and a growing share of vinifera, among them Cabernet Franc, Chardonnay, Riesling and Pinot Noir.', 'White wines from Seyval Blanc, Chardonnay, Riesling and Vidal Blanc, and red wines from Cabernet Franc, Baco Noir and Pinot Noir.', array['Established 1982 (27 CFR 9.47)', 'New York''s first AVA', 'Brotherhood Winery, begun in 1839, is the oldest continuously operating winery in the United States', 'About 446 acres under vine on 79 farms (New York Wine & Grape Foundation)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.new-york.hudson-river-region';
insert into public.wine_place_styles (wine_place_id, style, sort_order, editorial_status)
select id, 'WHITE', 0, 'PUBLISHED' from public.wine_places where canonical_key = 'united-states.new-york.hudson-river-region';
