-- united-states.new-york.long-island.north-fork-of-long-island
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA in eastern Suffolk County covering the townships of Riverhead, Southold and Shelter Island, between Long Island Sound and Peconic Bay, within the Long Island AVA. It is sheltered from the open Atlantic by the South Fork and the bay. Louisa and Alex Hargrave bought a potato farm here in 1972 and planted Long Island''s first modern vinifera vineyard.', 'Maritime: the surrounding water delays spring budbreak and holds off winter, giving a long season of about 225 days, with 3 to 4 inches of rain a month.', 'Deep, well-drained soils of medium to moderate texture on nearly level or gently sloping land.', 'Mostly vinifera: Merlot and Cabernet Franc lead the reds, with Chardonnay, Sauvignon Blanc and Cabernet Sauvignon.', 'Red wines from Merlot, Cabernet Franc and Cabernet Sauvignon, and white wines from Chardonnay and Sauvignon Blanc.', array['Established 1986 (27 CFR 9.113)', 'Suffolk County: Riverhead, Southold and Shelter Island townships', 'Takes in Shelter Island, Robins Island, Fishers Island and Plum Island (27 CFR 9.113)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.new-york.long-island.north-fork-of-long-island';
