-- united-states.new-york.long-island.the-hamptons-long-island
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA covering the South Fork of Long Island, all of the townships of Southampton and East Hampton in Suffolk County, Gardiners Island included, within the Long Island AVA. It faces the Atlantic directly and has fewer wineries than the North Fork. Farmers planted the first vinifera vineyards on the South Fork in 1979.', 'In direct contact with the Atlantic, which brings moderating breezes but also rougher weather as autumn approaches; like the rest of Long Island, it has a long, mild growing season.', 'Sandier than the North Fork''s, laid down on the outwash plain left as the last glacier in the area melted.', 'Mostly vinifera: Merlot and Chardonnay lead, with Cabernet Franc and Sauvignon Blanc.', 'Red wines from Merlot and Cabernet Franc, and white wines from Chardonnay and Sauvignon Blanc.', array['Established 1985 (27 CFR 9.101)', 'Suffolk County: Southampton and East Hampton townships', 'Bridgehampton Winery released its first wine in 1983 (New York Wine & Grape Foundation)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.new-york.long-island.the-hamptons-long-island';
