-- united-states.new-york.niagara-escarpment
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA of about 18,000 acres in Niagara County on the north-facing slope of the Niagara Escarpment, a band about 28 miles long between the 400- and 600-foot elevation lines, from Johnson Creek west through Gasport and Lockport to the Niagara River at Lewiston. Grapes were grown here before the Civil War, and most new plantings are vinifera.', 'Lake Ontario, up to about 800 feet deep, keeps autumn nights warmer and the season frost-free longer; warm air rising off the lake meets cooler air over the escarpment and keeps moving, giving about 205 frost-free days and little winter damage. Lake-effect snow insulates the vines in winter.', 'Shallow, well-drained soils of the Hilton-Ovid-Ontario association, gravelly limestone and clay loam over limestone laid down in a Paleozoic sea.', 'Native, hybrid and vinifera grapes; new plantings are mostly Riesling, Cabernet Franc, Pinot Noir and Chardonnay, with Cabernet Sauvignon.', 'Dry white and red wines from Riesling, Chardonnay, Cabernet Franc and Pinot Noir, and ice wine when a vintage allows.', array['Established 2005 (27 CFR 9.186)', 'Niagara County', 'About 1,067 acres under vine on 58 farms (New York Wine & Grape Foundation)', 'About 400 acres of vineyards at approval (T.D. TTB-33)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.new-york.niagara-escarpment';
