-- united-states.new-york.upper-hudson
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA of about 1,500 square miles north of the Hudson River Region, in Albany, Montgomery, Rensselaer, Saratoga, Schenectady, Schoharie and Washington counties, lying low between the Adirondack, Catskill and Berkshire mountains. With no large body of water to temper it, it grows cold-hardy hybrids, many bred at Cornell University or the University of Minnesota.', 'Continental and landlocked, with sudden swings in temperature and winters as cold as −25 °F; the season runs about 155 days and reaches 2,300 to 2,700 growing degree days, and frost can damage new shoots on clear spring nights.', 'Well-drained soils left by the Laurentide Ice Sheet, over nearly 2,000 feet of limestone and other sedimentary rock from a Paleozoic sea.', 'Cold-hardy hybrids: Marquette, Frontenac and La Crescent lead, with La Crosse.', 'Red wines from Marquette and Frontenac and aromatic white wines from La Crescent, dry to off-dry.', array['Established 2018 (27 CFR 9.264)', 'Albany, Montgomery, Rensselaer, Saratoga, Schenectady, Schoharie and Washington counties', '19 commercial vineyards on about 67.5 acres at approval (T.D. TTB-152)', 'About 117 acres under vine on 43 farms (New York Wine & Grape Foundation)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.new-york.upper-hudson';
insert into public.wine_place_styles (wine_place_id, style, sort_order, editorial_status)
