-- united-states.oregon.columbia-gorge
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA about 60 miles east of Portland that lies on both banks of the Columbia River, in Oregon and Washington: Hood River and Wasco counties, Oregon, and Skamania and Klickitat counties, Washington. The river cuts the only sea-level passage through the Cascade Range, and over a short distance the climate shifts from wet and marine-influenced in the west to dry high desert in the east.', 'Rainfall drops from about 36 inches a year near the Cascades to about 10 inches in the east, and winds funnelled through the gorge, often 10 to 20 mph or more, cool and dry the vineyards. Vineyards range from near sea level to about 2,000 feet.', 'Volcanic soils, lahar deposits, loess, silt and sand; the final rule names silty loams of the Chemawa, Underwood and McGowen series, on benchlands left by ancient lava flows.', 'Many varieties: Pinot Noir, Chardonnay, Gewürztraminer and Riesling in the cooler, wetter west, and Zinfandel and Cabernet Sauvignon in the drier east.', 'White wines from Chardonnay, Gewürztraminer and Riesling, and red wines from Pinot Noir in the west and from Zinfandel and Cabernet Sauvignon in the east.', array['Established 2004 (27 CFR 9.178)', 'Hood River and Wasco counties (Oregon); Skamania and Klickitat counties (Washington)', 'About 186,610 acres, 120,010 of them in Oregon (Oregon Wine Board)', 'About 925 acres planted (Oregon Wine Board)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.oregon.columbia-gorge';
