-- united-states.oregon.southern-oregon.rogue-valley
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A large AVA in Jackson and Josephine counties, within the Southern Oregon AVA, made up of three distinct valleys with progressively warmer climates along the Rogue River and its tributaries. It lies about 75 miles from the coast, framed by the Cascade, Siskiyou and Coast ranges. Peter Britt began growing grapes here around 1852 and in 1873 founded Valley View, Oregon''s first official winery.', 'Warm, dry summers, with nights much cooler than the days, which keeps acidity in the grapes and lengthens the ripening season.', 'Mainly stream sediments laid down by the Rogue River and its tributaries, varying from one of its three valleys to the next.', 'Cabernet Sauvignon, Syrah and Viognier lead, with Pinot Noir, Chardonnay and Pinot Gris.', 'Red wines from Cabernet Sauvignon, Syrah and Pinot Noir, and white wines from Viognier, Chardonnay and Pinot Gris.', array['Established 1991 (27 CFR 9.132)', 'Jackson and Josephine counties', 'About 5,635 acres planted (Oregon Wine Board)', 'Contains the Applegate Valley AVA']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.oregon.southern-oregon.rogue-valley';
