-- united-states.oregon.southern-oregon.rogue-valley.applegate-valley
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA in the Siskiyou Mountains of Jackson and Josephine counties, entirely within the Rogue Valley AVA, running about 50 miles north from the California border to the Rogue River near Grants Pass. The surrounding ranges shelter it from cool Pacific winds. Most vineyards lie on stream terraces and alluvial fans shaped by the Applegate River.', 'Hot days and cool nights, with vineyards at up to about 2,000 feet, sheltered from marine air by the mountains around it.', 'Deep, well-drained stream sediments on terraces and alluvial fans laid down by the Applegate River.', 'Merlot, Cabernet Sauvignon and Syrah lead, with Chardonnay, Tempranillo and Pinot Noir.', 'Full-bodied red wines in Bordeaux and Rhône styles from Merlot, Cabernet Sauvignon and Syrah, and white wine from Chardonnay.', array['Established 2000 (27 CFR 9.165)', 'Jackson and Josephine counties', 'About 278,190 acres, about 750 planted (Oregon Wine Board)', 'Modern winemaking here resumed in the 1970s']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.oregon.southern-oregon.rogue-valley.applegate-valley';
