-- united-states.oregon.southern-oregon.umpqua-valley
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA entirely within Douglas County in southwest Oregon, within the Southern Oregon AVA, known for the ''hundred valleys'' formed where three mountain ranges meet. German immigrants grew grapes here from the 1880s, and in 1961 Richard Sommer founded HillCrest Vineyard, where he planted Oregon''s first Pinot Noir vines. It contains the Elkton Oregon and Red Hill Douglas County, Oregon AVAs.', 'Three broad zones: the cool, marine-influenced north around Elkton, with about 50 inches of rain a year; a central zone near Roseburg that suits both cool- and warm-climate grapes; and a warmer, drier south.', 'Stream sediments, marine sedimentary bedrock and volcanic soils, changing from one small valley to the next.', 'Pinot Noir and Pinot Gris lead, with Syrah, Tempranillo, Merlot and Albariño.', 'Red wines from Pinot Noir, Syrah, Tempranillo and Merlot, and white wines from Pinot Gris and Albariño.', array['Established 1984 (27 CFR 9.89)', 'Douglas County', 'About 3,605 acres planted (Oregon Wine Board)', 'HillCrest Vineyard, founded by Richard Sommer in 1961']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.oregon.southern-oregon.umpqua-valley';
