-- united-states.oregon.southern-oregon.umpqua-valley.elkton-oregon
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA of about 74,900 acres in Douglas County, 33 miles inland from the Pacific along the Umpqua River, within the larger Umpqua Valley AVA. It is the coolest and wettest part of the Umpqua Valley, planted to cool-climate grapes.', 'Marine-influenced, with about 50 inches of rain a year, and cooling breezes along the Umpqua River through the growing season.', 'Residual clay, silt loam, alluvial deposits and river terraces, which hold moisture well and reduce the need to irrigate.', 'Pinot Noir leads, with Pinot Gris, Gewürztraminer and Riesling.', 'Red wine from Pinot Noir and white wines from Pinot Gris, Gewürztraminer and Riesling.', array['Established 2013 (27 CFR 9.229)', 'Douglas County', 'About 305 acres planted (Oregon Wine Board)', '''Elkton Oregon'' and ''Elkton OR'' are both terms of viticultural significance']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.oregon.southern-oregon.umpqua-valley.elkton-oregon';
