-- united-states.oregon.southern-oregon.umpqua-valley.red-hill-douglas-county-oregon
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A small AVA of about 5,600 acres around a single hill east of Interstate 5 near Rice Hill, between Yoncalla and Oakland in Douglas County, within the Umpqua Valley AVA. The Applegate and Scott pioneer families settled at its base in the mid-1800s, and Jesse Applegate planted Douglas County''s first vineyard nearby, in Yoncalla, in 1876.', 'Vineyards at 800 to 1,200 feet, without the shelter of the Coast Range, grow cooler than most of Southern Oregon.', 'Iron-rich, red volcanic Jory soils formed from uplifted ancient basalt.', 'Pinot Noir and Pinot Gris are the predominant grapes.', 'Red wine from Pinot Noir, leaner and more structured than elsewhere in Southern Oregon, and white wine from Pinot Gris.', array['Established 2005 (27 CFR 9.190)', 'Douglas County', 'About 460 acres planted (Oregon Wine Board)', 'Its boundary follows the 800-foot contour line (27 CFR 9.190)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.oregon.southern-oregon.umpqua-valley.red-hill-douglas-county-oregon';
