-- united-states.oregon.the-rocks-district-of-milton-freewater
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA of about 3,770 acres near Milton-Freewater in Umatilla County, wholly in Oregon. It lies within the Walla Walla Valley AVA, which in turn lies within the Columbia Valley AVA, on a gently sloping alluvial fan of the Walla Walla River covered in basalt cobbles. Italian immigrants grew grapes here from the 1860s, and modern planting began in the 1990s.', 'Sunny summers with wide swings between day and night and occasional days over 100 °F, at elevations of about 800 to 1,000 feet.', 'About 96% Freewater series soils, very cobbly loam and gravelly silt loam full of loose basalt gravel, cobbles and boulders; the stones encourage deep roots and radiate heat to the grapes.', 'Syrah leads, with Cabernet Sauvignon and Grenache.', 'Red wines, chiefly Syrah, with Cabernet Sauvignon and Grenache.', array['Established 2015 (27 CFR 9.249)', 'Umatilla County, Oregon', 'About 640 acres planted (Oregon Wine Board)', '''The Rocks of Milton-Freewater'' is also a term of viticultural significance']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.oregon.the-rocks-district-of-milton-freewater';
