-- united-states.oregon.willamette-valley.chehalem-mountains
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA of about 62,500 acres 19 miles southwest of Portland, in Clackamas, Washington and Yamhill counties, within the Willamette Valley AVA. The Chehalem Mountains are a single landmass of hilltops, ridges and spurs rising to 1,633 feet at Bald Peak. Dick Erath planted its first vineyard in 1968; it contains the Ribbon Ridge and Laurelwood District AVAs.', 'Cool, with the mountains sheltering many vineyards from Columbia Gorge winds; most vineyards lie between 200 and 1,000 feet.', 'Three main soil types: volcanic basalt, marine sediment, and wind-blown loess of the Laurelwood series.', 'Pinot Noir leads, with Chardonnay, Pinot Gris, Riesling, Pinot Blanc and Gamay.', 'Red wines from Pinot Noir and Gamay, and white wines from Chardonnay, Pinot Gris, Riesling and Pinot Blanc.', array['Established 2006 (27 CFR 9.205)', 'Clackamas, Washington and Yamhill counties', 'About 2,720 acres planted (Oregon Wine Board)', 'More than 50 wineries (Oregon Wine Board)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.oregon.willamette-valley.chehalem-mountains';
