-- united-states.oregon.willamette-valley.chehalem-mountains.laurelwood-district
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA of about 33,600 acres on the north- and east-facing slopes of the Chehalem Mountains, in Washington and Yamhill counties, entirely within the Chehalem Mountains and Willamette Valley AVAs. It is defined by the near-uniform presence of Laurelwood soil, and it includes the highest point in the Willamette Valley, 1,633 feet.', 'Much like the rest of the northern Willamette Valley, with vineyards between 200 and 1,000 feet on hilly to mountainous ground.', 'Laurelwood soil throughout: a base of basalt about 15 million years old topped by wind-blown silt (loess) laid down over the last 200,000 years, up to about 4 feet deep depending on elevation.', 'Pinot Noir leads, with Pinot Gris and Chardonnay.', 'Red wine from Pinot Noir and white wines from Pinot Gris and Chardonnay.', array['Established 2020 (27 CFR 9.269)', 'Washington and Yamhill counties', 'About 70 vineyards on about 975 acres, and 25 wineries (T.D. TTB-160)', 'Its boundary follows the 200-, 240- and 250-foot elevation contours in places (27 CFR 9.269)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.oregon.willamette-valley.chehalem-mountains.laurelwood-district';
