-- united-states.oregon.willamette-valley.chehalem-mountains.ribbon-ridge
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA of about 3,500 acres on a ridge in northern Yamhill County, northwest of Dundee, within the Chehalem Mountains AVA. The ridge stands above the Chehalem Valley floor like an island. Harry Peterson-Nedry planted Ridgecrest Vineyards here in 1980.', 'The ridge''s island-like position shelters it from weather extremes: it warms earlier in the day, cools less at night and escapes the sharpest midsummer heat, giving a long, cool growing season.', 'Marine sediments of the Willakenzie series, younger, finer and more uniform than the sedimentary and volcanic soils around the ridge; well drained and moderately deep.', 'Pinot Noir leads, with Chardonnay, Pinot Gris, Riesling and Gamay.', 'Red wines from Pinot Noir and Gamay, and white wines from Chardonnay, Pinot Gris and Riesling.', array['Established 2005 (27 CFR 9.182)', 'Yamhill County', 'About 620 acres planted (Oregon Wine Board)', 'Commercial grape growing began in 1982 and winemaking in 1985']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.oregon.willamette-valley.chehalem-mountains.ribbon-ridge';
