-- united-states.oregon.willamette-valley.dundee-hills
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA of hills near Newberg in Yamhill County, entirely within the Willamette Valley AVA; its boundary follows the 200-foot contour line where the hills rise from the flat valley floor. Oregon''s wine pioneers planted here from 1965, among them David Lett, Dick Erath, the Knudsens and the Sokol Blossers.', 'Warmer nights and less low-lying fog and frost than the valleys beside it, sheltered by the Chehalem Mountains to the north and the Coast Range to the west. Peaks pass 700 feet and reach 1,067 feet.', 'About 80% Jory series soils: reddish silt, clay and loam weathered from Columbia River basalt, moderately fertile and well drained.', 'Pinot Noir leads, with Chardonnay, Pinot Gris and Pinot Blanc.', 'Red wine from Pinot Noir, white wines from Chardonnay, Pinot Gris and Pinot Blanc, and sparkling wines.', array['Established 2004 (27 CFR 9.180)', 'Yamhill County', 'About 2,225 acres planted (Oregon Wine Board)', 'Proposed as ''Red Hills'', then renamed to avoid confusion with other areas (T.D. TTB-18)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.oregon.willamette-valley.dundee-hills';
