-- united-states.oregon.willamette-valley.eola-amity-hills
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA northwest of Salem in Polk and Yamhill counties, entirely within the Willamette Valley AVA. Its main ridge, the Eola Hills, runs north to south with lateral ridges running east to west. It lies directly east of the Van Duzer Corridor, a break in the Coast Range that lets cool Pacific air through.', 'Cool ocean air through the Van Duzer Corridor lowers late-summer afternoon temperatures sharply, helping grapes keep their acidity; vineyards lie mostly between 250 and 700 feet.', 'Volcanic basalt from ancient lava flows, with marine sedimentary rocks or alluvial deposits, giving shallow, rocky, well-drained soils.', 'Pinot Noir leads by far, with Chardonnay, Pinot Gris, Riesling and Gamay.', 'Red wines from Pinot Noir and Gamay, and white wines from Chardonnay, Pinot Gris and Riesling.', array['Established 2006 (27 CFR 9.202)', 'Polk and Yamhill counties', 'About 39,200 acres, about 3,040 planted (Oregon Wine Board)', 'Pinot Noir is about 80% of plantings (Willamette Valley Wineries Association)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.oregon.willamette-valley.eola-amity-hills';
