-- united-states.oregon.willamette-valley.lower-long-tom
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA of about 25,000 acres between Corvallis and Eugene in Benton and Lane counties, on the west side of the Lower Long Tom River watershed, within the Willamette Valley AVA. Its vineyards sit on stream-cut ridges running east to west.', 'A rain shadow cast by the Coast Range to the west reduces rainfall, and together with the prevailing winds keeps disease pressure low through the growing season.', 'Shallow Bellpine clay loams formed from uplifted ancient marine sediments, mainly sandstone, which vine roots must penetrate to reach water and nutrients.', 'Pinot Noir predominates, with Chardonnay, Riesling, Pinot Gris and Sauvignon Blanc.', 'Red wine from Pinot Noir and white wines from Chardonnay, Riesling, Pinot Gris and Sauvignon Blanc.', array['Established 2021 (27 CFR 9.281)', 'Benton and Lane counties', 'About 575 acres planted, 24 vineyards and 12 wineries (Willamette Valley Wineries Association)', 'Its boundary uses the 360-, 800- and 1,000-foot elevation contours (27 CFR 9.281)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.oregon.willamette-valley.lower-long-tom';
