-- united-states.oregon.willamette-valley.mcminnville
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA of about 39,045 acres due west of the town of McMinnville in Yamhill County, entirely within the Willamette Valley AVA, on the east and southeast slopes of the Coast Range foothills. It extends about 20 miles south-southwest toward the Van Duzer Corridor.', 'In the weather shadow of the Coast Range, with less rain than sites further east, and drying winds through the Van Duzer Corridor.', 'Uplifted marine sedimentary loams and silts with alluvial overlays on a basalt base, shallow for grape growing.', 'Pinot Noir makes up about 84% of plantings, with Chardonnay and Pinot Blanc.', 'Mostly red wine from Pinot Noir, with white wines from Chardonnay and Pinot Blanc.', array['Established 2005 (27 CFR 9.181)', 'Yamhill County', 'Vineyards between 200 and 1,000 feet (Willamette Valley Wineries Association)', 'About 750 acres planted in 16 vineyards (Willamette Valley Wineries Association)']::text[], 'PUBLISHED'
