-- united-states.oregon.willamette-valley.mount-pisgah-polk-county-oregon
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA of about 5,850 acres around a single mountain in Polk County, within the Willamette Valley AVA, rising from 260 feet at its base to 835 feet at the peak. ''Polk County, Oregon'' is part of the name because at least three other places in Oregon are called Mount Pisgah.', 'Cooler than the land nearby, averaging about 2,543 growing degree days against 2,903 at Salem, and much less windy, at an average of 2.3 mph against 6.1 mph at Salem.', 'Ancient sedimentary soils rather than the younger alluvium around the mountain: silty clay loams of the Bellpine, Jory, Nekia, Rickreall and Willakenzie series cover about 92% of the area.', 'Pinot Noir, Pinot Gris and Chardonnay are the most commonly grown grapes.', 'Red wine from Pinot Noir and white wines from Pinot Gris and Chardonnay.', array['Established 2022 (27 CFR 9.284)', 'Polk County', '10 commercial vineyards on about 531 acres, and 2 wineries (T.D. TTB-180)', '''Mt. Pisgah, Polk County, Oregon'' is also a term of viticultural significance']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.oregon.willamette-valley.mount-pisgah-polk-county-oregon';
