-- united-states.oregon.willamette-valley.van-duzer-corridor
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA of about 59,850 acres in Polk and Yamhill counties, within the Willamette Valley AVA, at the eastern end of a low wind gap in the Coast Range through which Pacific air flows into the valley. Its low, gently rolling hills widen from the narrow western gap toward the east.', 'Steady, strong winds from the ocean, arriving as early as 2 p.m., cool the vineyards; the wind thickens grape skins and reduces fungal pressure, and heat accumulation stays low.', 'Shallow, well-drained uplifted marine sedimentary loams and silts with alluvial overlay and some uplifted basalt, high in silt and clay, unlike the volcanic and loess soils around it.', 'Pinot Noir leads, with Chardonnay, Pinot Gris, Riesling, Pinot Blanc and Sauvignon Blanc.', 'Red wine from Pinot Noir and white wines from Chardonnay, Pinot Gris, Riesling, Pinot Blanc and Sauvignon Blanc.', array['Established 2018 (27 CFR 9.265)', 'Polk and Yamhill counties', '17 commercial vineyards on about 1,000 acres, and 6 wineries (T.D. TTB-155)', 'The Van Duzer Corridor is Oregon''s lowest pass through the Coast Range']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.oregon.willamette-valley.van-duzer-corridor';
