-- united-states.oregon.willamette-valley.yamhill-carlton
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA of about 59,000 acres around the hamlets of Carlton and Yamhill in Yamhill and Washington counties, entirely within the Willamette Valley AVA, limited by law to land between 200 and 1,000 feet. Low ridges ring the two towns in a horseshoe, with the North Yamhill River running through. It was named Yamhill-Carlton District until 2010.', 'Sheltered on three sides: the Coast Range to the west, nearly 3,500 feet high, casts a rain shadow, and the Chehalem Mountains to the north and the Dundee Hills to the east add further protection.', 'Coarse-grained ancient marine sediments, among the oldest soils in the valley, which drain quickly and leave the vines short of water.', 'Pinot Noir makes up about 80% of plantings, with Chardonnay and Pinot Gris.', 'Mostly red wine from Pinot Noir, with white wines from Chardonnay and Pinot Gris.', array['Established 2004 (27 CFR 9.183)', 'Yamhill and Washington counties', 'Limited to land between 200 and 1,000 feet (27 CFR 9.183)', 'About 2,844 acres planted in 127 vineyards (Willamette Valley Wineries Association)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.oregon.willamette-valley.yamhill-carlton';
