-- united-states.washington.columbia-valley.ancient-lakes-of-columbia-valley
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA of 162,762 acres in central Washington around the town of Quincy, in Douglas, Grant and Kittitas counties, with the Columbia River along its western edge. It is named for the lakes that dot its ice-age flood channels. It is one of the few Washington AVAs planted more to white grapes than to red, above all Riesling.', 'One of the more northerly parts of the Columbia Valley, with many vineyards a little higher than the valley around them, so heat builds later in the season and fades sooner. Wide swings between day and night help the grapes keep their acidity, and the Columbia River shields many sites from early and late frost.', 'Soils left by the Missoula Floods, mostly fine sand with silt and sandy loam; some sites, such as Evergreen Vineyard, have deposits of calcium-rich caliche. Most of the area slopes gently, at under 4%, toward its eastern boundary.', 'Riesling leads the plantings, with Chardonnay and Sauvignon Blanc among the more than 20 varieties grown.', 'Mostly white wines, led by Riesling, Chardonnay and Sauvignon Blanc, with some red wines.', array['Established 2012 (27 CFR 9.227)', 'About 162,762 acres, with six commercial vineyards on about 1,399 acres at approval (T.D. TTB-108)', 'Douglas, Grant and Kittitas counties', 'Part of the Channeled Scablands, carved by the ice-age floods']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.washington.columbia-valley.ancient-lakes-of-columbia-valley';
