-- united-states.washington.columbia-valley.horse-heaven-hills
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A large AVA in south-central Washington, in Benton, Klickitat and Yakima counties, rising north from the Columbia River. Its name comes from an early pioneer who, seeing its wide prairies, called it horse heaven. About a quarter of Washington''s wine-grape acreage is planted here, much of it on south-facing slopes.', 'Warm and windy, with an arid to semi-arid continental climate, so vineyards are irrigated. Steady winds keep canopies small and grape skins thick and discourage mold and rot, and the Columbia River tempers the risk of early and late frost.', 'Three main soil types, all well drained: wind-blown sand and loess, Missoula Flood sediment, and rubble washed down the hill slopes from the Columbia River basalt bedrock.', 'Cabernet Sauvignon makes up a large share of plantings, with Merlot, Chardonnay and Riesling.', 'Red wines led by Cabernet Sauvignon and Merlot, and white wines from Chardonnay and Riesling.', array['Established 2005 (27 CFR 9.188)', 'About 570,000 acres, about 17,082 under vine (Washington State Wine Commission)', 'Benton, Klickitat and Yakima counties', 'First vinifera planted in 1972, at what is now Champoux Vineyard']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.washington.columbia-valley.horse-heaven-hills';
insert into public.wine_place_styles (wine_place_id, style, sort_order, editorial_status)
