-- united-states.washington.columbia-valley.lake-chelan
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA of about 24,040 acres wrapped around the southern end of Lake Chelan in north-central Washington, in Chelan County, within the Columbia Valley AVA. Unlike most of the Columbia Valley it sits on granitic rather than basalt bedrock, and it lies north of the reach of the Missoula Floods. Its first modern vinifera plantings date from 1998.', 'The glacier-carved lake, up to 1,486 feet deep, moderates the climate: summer days are cooler and summer nights warmer than in the land around it. Vineyards lie along the southern and eastern shores at about 1,100 feet, higher than many southern parts of the Columbia Valley.', 'Glacial sediments with a good deal of quartz and mica, mixed with ash and pumice from the volcanoes of the Cascade Range.', 'Syrah and Pinot Noir lead, with Chardonnay, Pinot Gris, Merlot and Riesling.', 'Red wines from Syrah, Pinot Noir and Merlot, and white wines from Chardonnay, Pinot Gris and Riesling.', array['Established 2009 (27 CFR 9.215)', 'About 24,040 acres, about 269 under vine (Washington State Wine Commission)', 'Chelan County', 'Parts of its boundary follow the 2,000-foot elevation line (27 CFR 9.215)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.washington.columbia-valley.lake-chelan';
