-- united-states.washington.columbia-valley.naches-heights
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA of about 13,254 acres on a plateau northwest of Yakima, between the towns of Naches and Tieton in Yakima County, within the Columbia Valley AVA. It sits on a lava flow about a million years old with andesite bedrock, rather than the basalt found across most of the Columbia Valley. Its first vinifera were planted in 2002.', 'At 1,200 to 2,100 feet and close to the Cascades, it is cooler and wetter than much of the Columbia Valley, with 10 to 13 inches of rain a year. The plateau''s gentle grade lets cold air drain to lower ground, lowering the risk of frost.', 'Wholly above the level of the Missoula Floods, so the soils are wind-blown loess, still accumulating, with a good deal of clay that helps hold water.', 'Pinot Gris and Riesling lead, with Gewürztraminer and Syrah.', 'Mostly white wines from Pinot Gris, Riesling and Gewürztraminer, and red wine from Syrah.', array['Established 2011 (27 CFR 9.222)', 'About 13,254 acres (Washington State Wine Commission)', 'Yakima County', 'Every vineyard is farmed organically, biodynamically or Salmon-Safe, or a mix of these']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.washington.columbia-valley.naches-heights';
