-- united-states.washington.columbia-valley.rocky-reach
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA of about 32,333 acres straddling the Columbia River between Wenatchee and Lake Chelan, in Chelan and Douglas counties, within the Columbia Valley AVA. The river and the Rocky Reach Reservoir cover about a quarter of it. Its name comes from steamboat captains of the late 1800s, who used it for this rocky stretch of rapids.', 'The low terraces in the river canyon are warmer, with a longer growing season, than the mountains and plateaus around them, which lets grapes ripen this far north. About 11 inches of rain falls a year.', 'Wind-blown sand and silt over cobblestones and gravel left by glacial outwash and floods, on crystalline bedrock rich in quartz and mica, which among Columbia Valley AVAs it shares only with Lake Chelan. The stony surface warms quickly and gives off heat to the vines.', 'Cabernet Sauvignon is the leading grape on its roughly 117 acres of vineyards.', 'Mainly red wines, led by Cabernet Sauvignon.', array['Established 2022 (27 CFR 9.287)', 'Chelan and Douglas counties', '7 commercial vineyards on about 117 acres at approval (T.D. TTB-183)', 'About 24% of the area is river and reservoir']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.washington.columbia-valley.rocky-reach';
insert into public.wine_place_styles (wine_place_id, style, sort_order, editorial_status)
select id, 'RED', 0, 'PUBLISHED' from public.wine_places where canonical_key = 'united-states.washington.columbia-valley.rocky-reach';
