select p.id, g.id, 'PRINCIPAL', true, null, null, 'PUBLISHED'
  from public.wine_places p, public.grapes g
 where p.canonical_key = 'united-states.washington.columbia-valley.rocky-reach' and g.name = 'Cabernet Sauvignon';

-- united-states.washington.columbia-valley.royal-slope
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA of about 156,389 acres in Grant and Adams counties: a broad, mostly south-facing slope around Royal City between the Quincy Basin and the Saddle Mountains, within the Columbia Valley AVA. It lies between the Ancient Lakes AVA to the north and the Wahluke Slope to the south. Wine grapes were first planted here in 1983.', 'Cooler than the Wahluke Slope about 15 miles south and warmer than Ancient Lakes, with 6 to 8 inches of rain a year. Elevations run from 610 feet to 1,756 feet on the Frenchman Hills ridge; higher sites ripen later and keep more acidity, and the slope lets cold air drain away.', 'Fine sand with silt and sandy loam, on a slope that is part of the Yakima Fold Belt.', 'Cabernet Sauvignon leads, with Syrah and Chardonnay among a wide range of varieties.', 'Red wines led by Cabernet Sauvignon and Syrah, and white wines such as Chardonnay.', array['Established 2020 (27 CFR 9.271)', 'Grant and Adams counties', '13 commercial vineyards and one winery (Washington State Wine Commission)', 'Much of its boundary follows the 250-meter elevation contour (27 CFR 9.271)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.washington.columbia-valley.royal-slope';
