-- united-states.washington.columbia-valley.the-burn-of-columbia-valley
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA of about 16,870 acres in Klickitat County, on benches above the Columbia River west of the Horse Heaven Hills, within the Columbia Valley AVA. The name has been used for the area for more than 100 years, though its origin is unclear. Almost all of its vineyards have been planted since 2015.', 'It averages about 2,763 growing degree days, a little above the Columbia Valley''s norm, but steady winds from the nearby Columbia Gorge slow the vines and keep canopies and berries small, so harvest comes late. It averages 8.76 inches of rain a year, more than much of the valley.', 'Mainly silty loams of the Mollisol order, largely Walla Walla silt loam, which hold more water and organic matter than the soils around them, on southeast-facing benches with an average slope of about 7%.', 'Cabernet Sauvignon is the main grape, and Syrah the other most planted variety.', 'Red wines, chiefly from Cabernet Sauvignon and Syrah.', array['Established 2021 (27 CFR 9.276)', 'Klickitat County', '3 commercial vineyards on about 1,261 acres at approval (T.D. TTB-168)', 'Precipitation of about 6.7 to 10.4 inches a year across the area (T.D. TTB-168)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.washington.columbia-valley.the-burn-of-columbia-valley';
insert into public.wine_place_styles (wine_place_id, style, sort_order, editorial_status)
