-- united-states.washington.columbia-valley.wahluke-slope
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA of about 81,000 acres near Mattawa in Grant County, bounded by the Columbia River, the Saddle Mountains and the Hanford Reach National Monument, within the Columbia Valley AVA. The whole AVA sits on one large ancestral alluvial fan with a steady grade of under 8%. It holds about 15% of Washington''s vineyard acreage.', 'Among the warmest and driest parts of the state, with about 6 inches of rain a year. The slope and the nearby Columbia River lower the risk of frost; elevations run from 425 feet at the river to 1,480 feet, though most vineyards lie below 1,000 feet.', 'Deep wind-blown sand, more than 5 feet deep on average, which drains freely and makes vine vigor and ripening unusually even across the area.', 'Mainly red grapes, above all Cabernet Sauvignon, Merlot and Syrah, with Chardonnay.', 'Red wines from Cabernet Sauvignon, Merlot and Syrah, and some white wine from Chardonnay.', array['Established 2005 (27 CFR 9.192)', 'Grant County', 'About 8,932 acres under vine (Washington State Wine Commission)', 'Its name is a Native American term for ''watering place''']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.washington.columbia-valley.wahluke-slope';
