-- united-states.washington.columbia-valley.walla-walla-valley
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA of about 300,000 acres around the town of Walla Walla that spans Walla Walla County, Washington, and Umatilla County, Oregon; TTB lists both states. It lies within the Columbia Valley AVA and holds The Rocks District of Milton-Freewater, on the Oregon side. It has the highest concentration of wineries in Washington, including some of the state''s oldest.', 'Cooler and wetter than many Washington AVAs. Rainfall rises from about 9 inches a year in the west to 22 inches at the eastern edge in the foothills of the Blue Mountains, where a few vineyards can be farmed without irrigation.', 'Mostly well-drained sandy loess over Missoula Flood slackwater deposits and fractured basalt; above 1,200 feet, the floods'' high-water mark, the loess lies directly on basalt. In the south an old riverbed of cobblestones defines The Rocks District.', 'Mostly red grapes, led by Cabernet Sauvignon, Merlot and Syrah.', 'Mainly red wines from Cabernet Sauvignon, Merlot and Syrah.', array['Established 1984 (27 CFR 9.91)', 'About 2,933 acres under vine, 1,672 of them in Washington (Washington State Wine Commission)', 'More than 120 wineries (Washington State Wine Commission)', 'Its name comes from a Native American term meaning ''many waters''']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.washington.columbia-valley.walla-walla-valley';
insert into public.wine_place_styles (wine_place_id, style, sort_order, editorial_status)
