-- united-states.washington.columbia-valley.white-bluffs
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA of about 93,738 acres in Franklin County, on a plateau north of Pasco that rises about 200 feet above the land around it, within the Columbia Valley AVA. It is named for the whitish lake-bed sediments of the Ringold Formation, exposed in bluffs along the Columbia River. Its first vines were planted in 1972.', 'The plateau''s height lengthens the growing season by about 45 days on average compared with the surrounding area and helps protect vines from frost and freezes. About 6 inches of rain falls a year.', 'Wind-deposited silt and fine sand over ice-age flood sediment, on the clay-rich lake-bed sediments of the Ringold Formation and a thick layer of caliche, so vine roots never reach basalt.', 'Cabernet Sauvignon and Merlot lead, with Syrah, Riesling and Sauvignon Blanc.', 'Red wines from Cabernet Sauvignon, Merlot and Syrah, and white wines from Riesling and Sauvignon Blanc.', array['Established 2021 (27 CFR 9.275)', 'Franklin County', '9 commercial vineyards on about 1,127 acres, and one winery (T.D. TTB-167)', 'Elevations of about 700 to 1,200 feet (T.D. TTB-167)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.washington.columbia-valley.white-bluffs';
insert into public.wine_place_styles (wine_place_id, style, sort_order, editorial_status)
