-- united-states.washington.columbia-valley.yakima-valley
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'Washington''s first AVA, established in 1983 in Benton and Yakima counties within the Columbia Valley AVA, and the first in the Pacific Northwest. The Yakima River runs through it, and it holds nearly a third of the state''s planted vinifera acreage. It contains the Red Mountain, Rattlesnake Hills, Snipes Mountain, Goose Gap and Candy Mountain AVAs.', 'Cooler toward the Cascade foothills in the west and hot toward the center of the Columbia Basin, with about 8 inches of rain a year; the Yakima River and local aquifers supply water for irrigation.', 'Moderate to deep silt loam laid down by the Missoula Floods, over gravel or directly on basalt bedrock, well drained for irrigated vines.', 'One of the few Washington AVAs planted more to white grapes than red, led by Chardonnay and Riesling; its warmer sites grow Merlot, Cabernet Sauvignon and Syrah.', 'White wines from Chardonnay and Riesling, and red wines from Merlot, Cabernet Sauvignon and Syrah.', array['Established 1983 (27 CFR 9.69)', 'About 18,924 acres under vine (Washington State Wine Commission)', 'Benton and Yakima counties', 'Boundary extended by about 72 acres in 2020 to take in Candy Mountain (T.D. TTB-163)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.washington.columbia-valley.yakima-valley';
