-- united-states.washington.columbia-valley.yakima-valley.candy-mountain
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA of about 815 acres on the southwest-facing slope of Candy Mountain in Benton County, four miles southeast of Red Mountain. It lies within the Yakima Valley and Columbia Valley AVAs: T.D. TTB-163 extended Yakima Valley by about 72 acres to take it in whole. It is one of Washington''s smallest AVAs.', 'Warm and dry, with about 5 inches of rain a year, and windier than the land around it, much like Red Mountain nearby.', 'Thin soils of wind-deposited silt and fine sand over ice-age flood sediment and basalt bedrock; they hold little water, so growers can stress the vines as they choose.', 'Cabernet Sauvignon is the leading grape.', 'Red wines, mainly from Cabernet Sauvignon.', array['Established 2020 (27 CFR 9.272)', 'Benton County', 'Elevations of 640 to 1,320 feet, on slopes of 2 to 20 degrees (T.D. TTB-163)', 'About 110 acres under vine (Washington State Wine Commission)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.washington.columbia-valley.yakima-valley.candy-mountain';
