  from public.wine_places p, public.grapes g
 where p.canonical_key = 'united-states.washington.columbia-valley.yakima-valley.candy-mountain' and g.name = 'Cabernet Sauvignon';

-- united-states.washington.columbia-valley.yakima-valley.goose-gap
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA of about 8,129 acres in Benton County, taking in Goose Mountain and the gap between it and Badger and Candy mountains, within the Yakima Valley and Columbia Valley AVAs. Goose Mountain''s ridge runs east to west, unlike the northwest-trending ridges of Red Mountain, Candy Mountain and Rattlesnake Mountain, so most vines face north-northeast. The gap is named for the migratory waterfowl that pass through it.', 'On north-facing slopes the grapes receive less sun than on the south- and southwest-facing sites nearby and usually ripen later than the same varieties on Red Mountain. About 6 inches of rain falls a year.', 'Almost two thirds Warden series soils, wind-blown silt and fine sand over Missoula Flood sediment, with Kiona, Shano, Hezel and Prosser series; elevations run from 577 to 1,339 feet.', 'Cabernet Sauvignon leads, with Merlot, Syrah and Chardonnay among the 16 varieties planted.', 'Red wines led by Cabernet Sauvignon, Merlot and Syrah, and white wine from Chardonnay.', array['Established 2021 (27 CFR 9.277)', 'Benton County', 'Two vineyards on more than 1,800 acres, and one winery (T.D. TTB-170)', 'First vines planted in 1998 by Arvid Monson']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.washington.columbia-valley.yakima-valley.goose-gap';
