-- united-states.washington.columbia-valley.yakima-valley.rattlesnake-hills
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA of about 68,500 acres on the south slope of the Rattlesnake Hills around Zillah in Yakima County, within the Yakima Valley AVA. The hills are an east-west fold of the Yakima Fold Belt and take their name from nearby Rattlesnake Mountain. The earliest vines here were planted in 1968.', 'Generally higher than the Yakima Valley as a whole, from 850 to 3,085 feet, with vineyards on the lower ground; the height lessens the risk of spring and fall frost, and winters are milder than in the land around it. Rainfall is 6 to 12 inches a year.', 'Mostly silt loam and loam. About half the AVA is underlain by Ellensburg Formation sediments eroded from the Cascade volcanoes, and the higher vineyards lie above the reach of the Missoula Floods.', 'Fairly evenly split between red and white grapes, reds slightly ahead: Merlot, Cabernet Sauvignon, Syrah and Riesling lead.', 'Red wines from Merlot, Cabernet Sauvignon and Syrah, and white wine from Riesling.', array['Established 2006 (27 CFR 9.193)', 'Yakima County', 'About 1,807 acres under vine (Washington State Wine Commission)', 'Its boundary crosses Elephant Mountain, Zillah Peak and High Top Mountain (27 CFR 9.193)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.washington.columbia-valley.yakima-valley.rattlesnake-hills';
