-- united-states.washington.columbia-valley.yakima-valley.red-mountain
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA of about 4,040 acres near Benton City in Benton County, within the Yakima Valley AVA. Despite its name it is neither red nor a mountain but a fold of the Yakima Fold Belt with broad southwest-facing slopes; in spring its cheatgrass turns a reddish hue. Cabernet Sauvignon makes up about 60% of its plantings.', 'One of Washington''s warmest and driest AVAs, with about 5 inches of rain a year. The nearby Yakima River keeps the air moving and guards against frost, and nights can be as much as 40 °F cooler than days.', 'Sandy loam and gravel, alkaline and rich in calcium carbonate; the lean, high-pH soils limit vine vigor and keep berries small.', 'Cabernet Sauvignon dominates, with Merlot and Syrah.', 'Red wines, mainly Cabernet Sauvignon, Merlot and Syrah, often firmly tannic.', array['Established 2001 (27 CFR 9.167)', 'About 2,382 acres under vine (Washington State Wine Commission)', 'Elevations of about 500 to 1,500 feet', 'More than 15 wineries (Washington State Wine Commission)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.washington.columbia-valley.yakima-valley.red-mountain';
insert into public.wine_place_styles (wine_place_id, style, sort_order, editorial_status)
