-- united-states.washington.columbia-valley.yakima-valley.snipes-mountain
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA of about 4,145 acres on Snipes Mountain, a fold of the Yakima Fold Belt between Sunnyside and Granger in Yakima County, within the Yakima Valley AVA. It is named after cattle rancher Ben Snipes, who built a home at its base in the 1800s. Vineyards were first planted here in 1914, and Harrison Hill holds Cabernet Sauvignon vines from 1963.', 'Steep north- and south-facing slopes let cold air drain downhill, helping to prevent the frost damage that sometimes hits nearby areas. About 7 inches of rain falls a year.', 'Loess over Missoula Flood sediment and, in many places, fist- to melon-sized cobbles and gravel laid down by an ancestral course of the Columbia River; only the top 90 feet of the mountain rise above the floods.', 'Chardonnay, Cabernet Sauvignon and Merlot lead the plantings.', 'Red wines from Cabernet Sauvignon and Merlot, and white wine from Chardonnay.', array['Established 2009 (27 CFR 9.213)', 'Yakima County', 'About 859 acres under vine (Washington State Wine Commission)', 'Its boundary follows the 750-foot and 820-foot elevation contours (27 CFR 9.213)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.washington.columbia-valley.yakima-valley.snipes-mountain';
