 where p.canonical_key = 'united-states.washington.columbia-valley.yakima-valley.snipes-mountain' and g.name = 'Merlot';

do $$
declare r record; n int;
begin
  -- Every row the data asked for is present. A grape name that failed to
  -- resolve would show up here as a short count rather than as silence.
  for r in
    select * from (values
    ('united-states.new-york.champlain-valley-of-new-york', 2, 3, 1),
    ('united-states.new-york.finger-lakes.cayuga-lake', 2, 5, 1),
    ('united-states.new-york.finger-lakes.seneca-lake', 3, 6, 1),
    ('united-states.new-york.hudson-river-region', 2, 7, 1),
    ('united-states.new-york.long-island.north-fork-of-long-island', 2, 5, 1),
    ('united-states.new-york.long-island.the-hamptons-long-island', 2, 4, 1),
    ('united-states.new-york.niagara-escarpment', 3, 5, 1),
    ('united-states.new-york.upper-hudson', 2, 3, 1),
    ('united-states.oregon.columbia-gorge', 2, 6, 1),
    ('united-states.oregon.southern-oregon.rogue-valley', 2, 6, 1),
    ('united-states.oregon.southern-oregon.rogue-valley.applegate-valley', 2, 6, 1),
    ('united-states.oregon.southern-oregon.umpqua-valley', 2, 6, 1),
    ('united-states.oregon.southern-oregon.umpqua-valley.elkton-oregon', 2, 4, 1),
    ('united-states.oregon.southern-oregon.umpqua-valley.red-hill-douglas-county-oregon', 2, 2, 1),
    ('united-states.oregon.the-rocks-district-of-milton-freewater', 1, 3, 1),
    ('united-states.oregon.willamette-valley.chehalem-mountains', 2, 6, 1),
    ('united-states.oregon.willamette-valley.chehalem-mountains.laurelwood-district', 2, 3, 1),
    ('united-states.oregon.willamette-valley.chehalem-mountains.ribbon-ridge', 2, 5, 1),
    ('united-states.oregon.willamette-valley.dundee-hills', 3, 4, 1),
    ('united-states.oregon.willamette-valley.eola-amity-hills', 2, 5, 1),
    ('united-states.oregon.willamette-valley.lower-long-tom', 2, 5, 1),
    ('united-states.oregon.willamette-valley.mcminnville', 2, 3, 1),
    ('united-states.oregon.willamette-valley.mount-pisgah-polk-county-oregon', 2, 3, 1),
    ('united-states.oregon.willamette-valley.tualatin-hills', 2, 4, 1),
    ('united-states.oregon.willamette-valley.van-duzer-corridor', 2, 6, 1),
    ('united-states.oregon.willamette-valley.yamhill-carlton', 2, 3, 1),
    ('united-states.washington.columbia-valley.ancient-lakes-of-columbia-valley', 2, 3, 1),
    ('united-states.washington.columbia-valley.horse-heaven-hills', 2, 4, 1),
    ('united-states.washington.columbia-valley.lake-chelan', 2, 6, 1),
    ('united-states.washington.columbia-valley.naches-heights', 2, 4, 1),
    ('united-states.washington.columbia-valley.rocky-reach', 1, 1, 1),
    ('united-states.washington.columbia-valley.royal-slope', 2, 3, 1),
    ('united-states.washington.columbia-valley.the-burn-of-columbia-valley', 1, 2, 1),
    ('united-states.washington.columbia-valley.wahluke-slope', 2, 4, 1),
    ('united-states.washington.columbia-valley.walla-walla-valley', 1, 3, 1),
    ('united-states.washington.columbia-valley.white-bluffs', 2, 5, 1),
    ('united-states.washington.columbia-valley.yakima-valley', 2, 5, 1),
    ('united-states.washington.columbia-valley.yakima-valley.candy-mountain', 1, 1, 1),
    ('united-states.washington.columbia-valley.yakima-valley.goose-gap', 2, 4, 1),
    ('united-states.washington.columbia-valley.yakima-valley.rattlesnake-hills', 2, 4, 1),
    ('united-states.washington.columbia-valley.yakima-valley.red-mountain', 1, 3, 1),
    ('united-states.washington.columbia-valley.yakima-valley.snipes-mountain', 2, 3, 1)
    ) as t(key, want_styles, want_grapes, want_article)
  loop
    select count(*) into n from public.wine_place_styles s
      join public.wine_places p on p.id = s.wine_place_id where p.canonical_key = r.key;
    if n <> r.want_styles then
      raise exception '%: % style rows, expected %', r.key, n, r.want_styles;
    end if;
    select count(*) into n from public.wine_place_grapes g
      join public.wine_places p on p.id = g.wine_place_id where p.canonical_key = r.key;
    if n <> r.want_grapes then
      raise exception '%: % grape rows, expected % — a grape name did not resolve', r.key, n, r.want_grapes;
    end if;
    select count(*) into n from public.wine_place_articles a
      join public.wine_places p on p.id = a.wine_place_id where p.canonical_key = r.key;
    if n < r.want_article then
      raise exception '%: no article', r.key;
    end if;
  end loop;

  -- No region or subregion in united-states is left without wine styles.
  select count(*) into n from public.wine_places p
   where p.kind in ('REGION','SUBREGION')
     and (p.canonical_key like 'united-states.%')
     and not exists (select 1 from public.wine_place_styles s where s.wine_place_id = p.id);
  if n <> 0 then raise exception '% places still have no wine styles', n; end if;

  -- Country level too: germany and spain always had rows and the other three
  -- did not, which was an inconsistency with no reason behind it.
  select count(*) into n from public.wine_places p
   where p.kind = 'COUNTRY' and (p.canonical_key like 'united-states')
     and not exists (select 1 from public.wine_place_styles s where s.wine_place_id = p.id);
  if n <> 0 then raise exception '% countries still have no wine styles', n; end if;

  -- ...or without an article.
  select count(*) into n from public.wine_places p
   where p.kind in ('REGION','SUBREGION')
     and (p.canonical_key like 'united-states.%')
     and not exists (select 1 from public.wine_place_articles a where a.wine_place_id = p.id);
  if n <> 0 then raise exception '% places still have no article', n; end if;
end $$;

